//! 📦️ An actual exhausted callback returns its original Fault and independent qualifier through held source custody.
use semio_framework_job_context::testkit;
use super::*;
use crate::{InteractiveJob,OriginalJobFixtureCaller,OperationId,Generation,OriginalTurnFailure,OriginalDomainProjection,OriginalDomainView};
use crate::original_failure_test_support::{projected,wire_value,wire_progress,independent_body};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress as P,ValueError};
use semio_framework_diagnostic::FaultMessageOwner;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
struct NativeProjection<'a>(&'a OriginalTurnFailure);
impl OriginalDomainProjection for NativeProjection<'_>{
 fn projection_identity(&self)->usize{self.0 as*const _ as usize}
 fn projection_view(&self,path:&[usize])->Result<OriginalDomainView<'_>,ValueError>{crate::project_original_turn_failure(self.0,path)}
 fn projection_key(&self,path:&[usize],index:usize)->Result<&str,ValueError>{crate::key_original_turn_failure(self.0,path,index)}
}
#[test]
fn exhausted_invalid_callback_keeps_full_owned_causes_until_cancelled_same_source_receive_and_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let source=&law["source"];let stock=RetainedCloneGrant{maximum_items:source["items"].as_u64().unwrap()as usize,maximum_copy_bytes:source["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:source["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:source["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:source["depth"].as_u64().unwrap()as usize};let mut caller=OriginalJobFixtureCaller::admit(OperationId(7523),Generation(7),stock,||Some(0),source["deadlineUs"].as_u64().unwrap(),source["fuel"].as_u64().unwrap());let q=crate::quantum(&mut caller,stock);let mut origin=OriginalJobReturnOrigin::empty();let mut owner=None;let message=law["ownedCapsule"]["message"].as_str().unwrap();let mut pointer=0;caller.turn(stock,|cx|{let turn=FaultMessageOwner::construct(message,cx.retained_grant());cx.consume_work(turn.work);let(value,p)=turn.result?;cx.consume_retained(p)?;pointer=value.fault().unwrap().message.as_ptr()as usize;owner=Some(value);Ok(())}).unwrap();
 for _ in 0..law["returnOrigin"]["maximumSetupTurns"].as_u64().unwrap(){let mut ready=false;caller.turn(q,|cx|cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|{ready=origin.admit(cx)?;Ok(())})).unwrap();if ready{break}}
 let mut pending=None;caller.turn(q,|cx|cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|{let claim=origin.enter_body(cx)?.expect("admitted actual return receiver");let mut fault=None;let(turn,heap)=observe(||owner.as_mut().unwrap().take_step(&mut fault,cx.retained_grant()));let p=turn.result?.progress();cx.consume_retained(p)?;cx.consume_work(turn.work);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert_eq!(cx.fuel_remaining(),0);assert_eq!(cx.retained_grant().maximum_items,0);let mut failure=OriginalTurnFailure::from(fault.take().unwrap());failure.effects=p;let operation=cx.operation();*testkit::operation_mut(cx)=OperationId(operation.0+1);let bank=testkit::return_budget_snapshot(cx);let(returned,heap)=observe(||claim.finish(cx,InteractiveJobStep::Continuation(failure),None));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));pending=Some(match returned{OriginalJobReturn::Continuation(continuation)=>continuation,_=>panic!("actual native return must own its continuation")});assert_eq!(testkit::return_budget_snapshot(cx),bank);assert_eq!((bank.held_items,bank.held_fuel),(2,2));let mut sequence=0;let mut recipient=P::default();let(result,heap)=observe(||origin.parent().unwrap().borrow_context(crate::StepBudget::new(1,cx.original_absolute_deadline_us(),q),cx.clock_source(),&mut sequence,&mut recipient));match &result{Err(error)=>assert_eq!(error.kind,semio_framework_value::ValueRefusalKind::WorkLimit),Ok(_)=>panic!("genuine source gate is already borrowed by the callback")};drop(result);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(pending.is_some());let before=cx.retained_progress();let work=cx.original_work_units_spent();assert!(origin.receive_continuation(cx,&mut pending).is_err());assert!(pending.is_some());assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent(),work);*testkit::operation_mut(cx)=operation;for invalid in [usize::MAX-1,usize::MAX]{let posted=cx.retained_progress();testkit::retained_progress_mut(cx).copied_items=invalid;let result=origin.receive_continuation(cx,&mut pending);*testkit::retained_progress_mut(cx)=posted;assert!(result.is_err());assert!(pending.is_some());assert_eq!(testkit::return_budget_snapshot(cx),bank);}cx.original_cancel_token().cancel_now();let(result,heap)=observe(||origin.receive_continuation(cx,&mut pending));assert!(result?);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(pending.is_none());assert_eq!(cx.reserved_return_work(),law["ownedCapsule"]["receiverActualReservedWork"].as_u64().unwrap());assert_eq!(cx.fuel_remaining(),0);let capsule=origin.continuation().unwrap();let callback=capsule.view().callback.unwrap();assert_eq!(callback.primary_fault().unwrap().message.as_ptr()as usize,pointer);assert_eq!(projected(&NativeProjection(callback),&mut Vec::new()),serde_json::json!({"primary":{"kind":"fault","original":independent_body(0,message)["fault"]},"effects":wire_progress(p)}));let qualifier=capsule.view().qualification.unwrap();assert_eq!(projected(&NativeProjection(qualifier),&mut Vec::new()),serde_json::json!({"primary":{"kind":"value","original":wire_value("invariantViolated",law["ownedCapsule"]["qualificationMessage"].as_str().unwrap(),P::default())},"effects":wire_progress(P::default())}));Ok(())})).unwrap();
 for _ in 0..4096{if origin.terminal_is_empty(){break}caller.turn(stock,|cx|{let before=cx.retained_progress();let(result,heap)=observe(||origin.close_step(cx));result?;let p=crate::original_failure_test_support::delta(before,cx.retained_progress());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));Ok(())}).unwrap();}assert!(origin.terminal_is_empty());caller.turn(stock,|cx|{crate::original_failure_test_support::close(owner.take(),cx,4096);Ok(())}).unwrap();let(_,heap)=observe(||drop(origin));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));caller.retire(stock);
}

struct ActualFailureJob{owner:FaultMessageOwner,calls:usize}
impl crate::InteractiveJob for ActualFailureJob{
 fn step<'job>(&'job mut self,cx:&mut crate::StepContext<'_>,_:&mut crate::OriginalJobReturnClaim<'_>)->crate::InteractiveJobStep<'job>{self.calls+=1;crate::InteractiveJobStep::from_callback((||{let mut output=None;let turn=self.owner.take_step(&mut output,cx.retained_grant());let result=turn.result;cx.consume_work(turn.work);let p=result?.progress();cx.consume_retained(p)?;let mut failure=OriginalTurnFailure::from(output.take().expect("actual owned Fault transfer"));failure.effects=p;Err(failure)})())}
 fn borrow_outcome<'job>(&'job self,_:&'job crate::JobOutcomeDescriptor)->Result<crate::JobOutcomeView<'job>,ValueError>{Err(ValueError::literal(semio_framework_value::ValueRefusalKind::UnsupportedOwner,"owned continuation has no semantic payload loan"))}
 fn begin_close(&mut self){}
 fn close_step(&mut self,cx:&mut crate::StepContext<'_>)->Result<crate::InteractiveJobCloseStep,OriginalTurnFailure>{let demand=self.owner.close_demand();crate::close_original_retained_step(cx,demand,|grant|self.owner.close_step(grant))}
 fn terminal_is_empty(&self)->bool{self.owner.terminal_is_empty()}
}
#[test]
fn actual_driver_keeps_a_claim_across_quantum_one_preparation_then_returns_the_owned_arm(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let source=&fixture["source"];let stock=RetainedCloneGrant{maximum_items:source["items"].as_u64().unwrap()as usize,maximum_copy_bytes:source["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:source["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:source["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:source["depth"].as_u64().unwrap()as usize};let mut caller=OriginalJobFixtureCaller::admit(OperationId(7526),Generation(7),stock,||Some(0),source["deadlineUs"].as_u64().unwrap(),source["fuel"].as_u64().unwrap());let q=crate::quantum(&mut caller,stock);let mut owner=None;caller.turn(stock,|cx|{let turn=FaultMessageOwner::construct(fixture["ownedCapsule"]["message"].as_str().unwrap(),cx.retained_grant());cx.consume_work(turn.work);let(value,p)=turn.result?;cx.consume_retained(p)?;owner=Some(value);Ok(())}).unwrap();let mut job=ActualFailureJob{owner:owner.take().unwrap(),calls:0};let mut origin=OriginalJobReturnOrigin::empty();let mut delivered=false;
 for _ in 0..fixture["returnOrigin"]["maximumSetupTurns"].as_u64().unwrap()+1{caller.turn(q,|cx|cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|{let mut verdict=None;let returned=if origin.admit(cx)?{semio_framework_job::drive_step(&mut job,cx,origin.receiver()?,"job.actual-owned-return",crate::InteractiveStage::InteractiveStep,&mut verdict)?}else{crate::OriginalJobReturn::Preparing};match returned{crate::OriginalJobReturn::Preparing=>{assert_eq!(job.calls,0);assert!(verdict.is_none());},crate::OriginalJobReturn::Pending=>panic!("actual Fault callback must retain its failure"),crate::OriginalJobReturn::Outcome(_)=>panic!("actual Fault callback must return an owned continuation"),crate::OriginalJobReturn::Continuation(value)=>{let mut returned=Some(value);assert!(origin.receive_continuation(cx,&mut returned)?);assert!(returned.is_none());assert!(verdict.is_some());assert_eq!(cx.fuel_remaining(),0);assert_eq!(cx.reserved_return_work(),2);delivered=true;}}Ok(())})).unwrap();if delivered{break}}assert!(delivered);assert_eq!(job.calls,1);assert!(job.terminal_is_empty());assert_eq!(origin.continuation().unwrap().view().callback.unwrap().primary_fault().unwrap().message,fixture["ownedCapsule"]["message"].as_str().unwrap());
 for _ in 0..4096{if origin.terminal_is_empty(){break}caller.turn(stock,|cx|{origin.close_step(cx)?;Ok(())}).unwrap();}assert!(origin.terminal_is_empty());drop(origin);drop(job);caller.retire(stock);
}

struct ReadOnlyFailureJob;
impl crate::InteractiveJob for ReadOnlyFailureJob{
 fn step<'job>(&'job mut self,_:&mut crate::StepContext<'_>,_:&mut crate::OriginalJobReturnClaim<'_>)->crate::InteractiveJobStep<'job>{crate::InteractiveJobStep::Continuation(ValueError::literal(semio_framework_value::ValueRefusalKind::InvalidValue,"actual read-only declaration rejection").into())}
 fn borrow_outcome<'job>(&'job self,_:&'job crate::JobOutcomeDescriptor)->Result<crate::JobOutcomeView<'job>,ValueError>{Err(ValueError::literal(semio_framework_value::ValueRefusalKind::UnsupportedOwner,"readonly failure has no semantic payload"))}
 fn begin_close(&mut self){}
 fn close_step(&mut self,_:&mut crate::StepContext<'_>)->Result<crate::InteractiveJobCloseStep,OriginalTurnFailure>{Ok(crate::InteractiveJobCloseStep::Complete{progress:P::default()})}
 fn terminal_is_empty(&self)->bool{true}
}
struct ActualYieldJob;
impl crate::InteractiveJob for ActualYieldJob{
 fn step<'job>(&'job mut self,cx:&mut crate::StepContext<'_>,_:&mut crate::OriginalJobReturnClaim<'_>)->crate::InteractiveJobStep<'job>{crate::InteractiveJobStep::from_callback(crate::JobOutcomeBorrow::admit_yield(cx).map_err(OriginalTurnFailure::from))}
 fn borrow_outcome<'job>(&'job self,descriptor:&'job crate::JobOutcomeDescriptor)->Result<crate::JobOutcomeView<'job>,ValueError>{descriptor.yielded()}
 fn begin_close(&mut self){}
 fn close_step(&mut self,_:&mut crate::StepContext<'_>)->Result<crate::InteractiveJobCloseStep,OriginalTurnFailure>{Ok(crate::InteractiveJobCloseStep::Complete{progress:P::default()})}
 fn terminal_is_empty(&self)->bool{true}
}
fn source_fixture(operation:u64)->(serde_json::Value,RetainedCloneGrant,OriginalJobFixtureCaller){let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let s=&law["source"];let stock=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let caller=OriginalJobFixtureCaller::admit(OperationId(operation),Generation(7),stock,||Some(0),s["deadlineUs"].as_u64().unwrap(),s["fuel"].as_u64().unwrap());(law,stock,caller)}
fn close_origin(origin:&mut OriginalJobReturnOrigin,caller:&mut OriginalJobFixtureCaller,stock:RetainedCloneGrant){for _ in 0..4096{if origin.terminal_is_empty(){break}caller.turn(stock,|cx|{let before=cx.retained_progress();let(result,heap)=observe(||origin.close_step(cx));result?;let p=crate::original_failure_test_support::delta(before,cx.retained_progress());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));Ok(())}).unwrap();}assert!(origin.terminal_is_empty());}
#[test]
fn actual_readonly_callback_has_zero_child_work_and_only_its_real_return_work(){
 let(law,stock,mut caller)=source_fixture(7528);let q=RetainedCloneGrant{maximum_items:1,..stock};let mut origin=OriginalJobReturnOrigin::empty();let mut job=ReadOnlyFailureJob;let mut delivered=false;for _ in 0..law["returnOrigin"]["maximumSetupTurns"].as_u64().unwrap()+1{caller.turn(q,|cx|cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|{let mut verdict=None;let returned=if origin.admit(cx)?{semio_framework_job::drive_step(&mut job,cx,origin.receiver()?,"job.actual-readonly-return",crate::InteractiveStage::InteractiveStep,&mut verdict)?}else{crate::OriginalJobReturn::Preparing};if let crate::OriginalJobReturn::Continuation(value)=returned{assert_eq!(cx.original_work_units_spent(),0);assert_eq!(cx.retained_progress().copied_items,testkit::original_total_retained_start(cx).copied_items);let mut input=Some(value);assert!(origin.receive_continuation(cx,&mut input)?);assert_eq!(cx.original_work_units_spent(),2);assert_eq!(cx.reserved_return_work(),2);assert_eq!(cx.fuel_remaining(),1);let callback=origin.continuation().unwrap().view().callback.unwrap();assert_eq!(projected(&NativeProjection(callback),&mut Vec::new()),serde_json::json!({"primary":{"kind":"value","original":wire_value("invalidValue",law["readOnlyCallback"]["message"].as_str().unwrap(),P::default())},"effects":wire_progress(P::default())}));delivered=true;}Ok(())})).unwrap();if delivered{break}}assert!(delivered);close_origin(&mut origin,&mut caller,stock);drop(origin);caller.retire(stock);
}
#[test]
fn normal_semantic_return_owns_its_receiving_witness_and_never_renews_quantum_one(){
 let(law,stock,mut caller)=source_fixture(7529);let q=RetainedCloneGrant{maximum_items:1,..stock};let mut origin=OriginalJobReturnOrigin::empty();let mut job=ActualYieldJob;let mut delivered=false;for _ in 0..law["returnOrigin"]["maximumSetupTurns"].as_u64().unwrap()+1{caller.turn(q,|cx|cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|{let mut verdict=None;let returned=if origin.admit(cx)?{semio_framework_job::drive_step(&mut job,cx,origin.receiver()?,"job.actual-semantic-return",crate::InteractiveStage::InteractiveStep,&mut verdict)?}else{crate::OriginalJobReturn::Preparing};match returned{crate::OriginalJobReturn::Preparing=>{},crate::OriginalJobReturn::Pending=>panic!("yield metadata was not admitted"),crate::OriginalJobReturn::Continuation(_)=>panic!("actual yielded metadata must remain semantic"),crate::OriginalJobReturn::Outcome(reply)=>{assert_eq!(cx.original_work_units_spent(),1);assert_eq!(cx.fuel_remaining(),0);assert_eq!(reply.original().unwrap().admission().progress(),P{copied_items:1,..Default::default()});let mut input=Some(reply.into_descriptor());assert!(origin.receive_outcome(cx,&mut input)?);assert!(input.is_none());assert_eq!(cx.original_work_units_spent(),2);assert_eq!(cx.reserved_return_work(),1);assert_eq!(cx.fuel_remaining(),0);assert_eq!(origin.outcome().unwrap().kind(),crate::JobOutcomeKind::Yield);let before=cx.retained_progress();let work=cx.original_work_units_spent();assert!(origin.receive_outcome(cx,&mut input)?);assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent(),work);delivered=true;}}Ok(())})).unwrap();if delivered{break}}assert!(delivered);close_origin(&mut origin,&mut caller,stock);drop(origin);caller.retire(stock);
}

#[test]
fn paid_cancel_close_waits_for_the_actual_owned_arm_instead_of_spending_its_delivery_without_it(){
 let(law,stock,mut caller)=source_fixture(7530);let q=RetainedCloneGrant{maximum_items:1,..stock};let mut origin=OriginalJobReturnOrigin::empty();let mut job=ReadOnlyFailureJob;let mut pending=None;for _ in 0..law["returnOrigin"]["maximumSetupTurns"].as_u64().unwrap()+1{caller.turn(q,|cx|cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|{let mut verdict=None;let returned=if origin.admit(cx)?{semio_framework_job::drive_step(&mut job,cx,origin.receiver()?,"job.actual-inflight-return",crate::InteractiveStage::InteractiveStep,&mut verdict)?}else{crate::OriginalJobReturn::Preparing};if let crate::OriginalJobReturn::Continuation(value)=returned{pending=Some(value);}Ok(())})).unwrap();if pending.is_some(){break}}assert!(pending.is_some());caller.cancel().cancel_now();caller.turn(q,|cx|{let work=cx.original_work_units_spent();let p=origin.close_step(cx)?.progress();assert_eq!(p,P{copied_items:1,..Default::default()});assert_eq!(cx.original_work_units_spent()-work,1);Ok(())}).unwrap();
 caller.turn(q,|cx|cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();let bank=testkit::return_budget_snapshot(cx);let(result,heap)=observe(||origin.close_step(cx));assert!(matches!(result?,crate::InteractiveJobCloseStep::Blocked));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent(),work);assert_eq!(testkit::return_budget_snapshot(cx),bank);assert_eq!((bank.held_items,bank.held_fuel),(2,2));assert!(pending.is_some());assert!(origin.receive_continuation(cx,&mut pending)?);assert!(pending.is_none());assert_eq!(cx.reserved_return_work(),2);assert_eq!(cx.fuel_remaining(),1);Ok(())})).unwrap();close_origin(&mut origin,&mut caller,stock);drop(origin);caller.retire(stock);
}

struct ActualPendingJob{remaining:usize}
impl crate::InteractiveJob for ActualPendingJob{
 fn step<'job>(&'job mut self,cx:&mut crate::StepContext<'_>,_:&mut crate::OriginalJobReturnClaim<'_>)->crate::InteractiveJobStep<'job>{crate::InteractiveJobStep::from_callback((||{if self.remaining==0{return crate::JobOutcomeBorrow::admit_yield(cx).map_err(OriginalTurnFailure::from)}if cx.should_yield()||cx.retained_grant().maximum_items==0||cx.retained_grant().maximum_depth==0{return Ok(None)}self.remaining-=1;let received=cx.consume_retained(P{copied_items:1,..Default::default()});cx.consume_fuel(1);received?;Ok(None)})())}
 fn borrow_outcome<'job>(&'job self,descriptor:&'job crate::JobOutcomeDescriptor)->Result<crate::JobOutcomeView<'job>,ValueError>{descriptor.yielded()}
 fn begin_close(&mut self){}
 fn close_step(&mut self,_:&mut crate::StepContext<'_>)->Result<crate::InteractiveJobCloseStep,OriginalTurnFailure>{Ok(crate::InteractiveJobCloseStep::Complete{progress:P::default()})}
 fn terminal_is_empty(&self)->bool{true}
}
#[test]
fn actual_pending_work_keeps_its_original_claim_instead_of_charging_a_receiving_turn_every_quantum(){
 let(law,stock,mut caller)=source_fixture(7531);let q=RetainedCloneGrant{maximum_items:1,..stock};let steps=law["protocol"]["pendingSteps"].as_u64().unwrap()as usize;let mut job=ActualPendingJob{remaining:steps};let mut origin=OriginalJobReturnOrigin::empty();let mut serial=None;let mut pending_count=0;let mut delivered=false;for _ in 0..law["returnOrigin"]["maximumSetupTurns"].as_u64().unwrap()+steps as u64+1{caller.turn(q,|cx|cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|{let mut verdict=None;let returned=if origin.admit(cx)?{semio_framework_job::drive_step(&mut job,cx,origin.receiver()?,"job.actual-pending-return",crate::InteractiveStage::InteractiveStep,&mut verdict)?}else{crate::OriginalJobReturn::Preparing};match returned{crate::OriginalJobReturn::Preparing=>{},crate::OriginalJobReturn::Pending=>{let bank=testkit::return_budget_snapshot(cx);assert_eq!((bank.held_items,bank.held_fuel,bank.claims),(2,2,1));if let Some(first)=serial{assert_eq!(bank.serial,first)}else{serial=Some(bank.serial)}assert_eq!(cx.original_work_units_spent(),1);assert_eq!(cx.reserved_return_work(),0);assert_eq!(cx.fuel_remaining(),0);pending_count+=1;},crate::OriginalJobReturn::Outcome(reply)=>{let bank=testkit::return_budget_snapshot(cx);assert_eq!(Some(bank.serial),serial);let mut returned=Some(reply.into_descriptor());origin.receive_outcome(cx,&mut returned)?;assert_eq!(cx.reserved_return_work(),1);delivered=true;},crate::OriginalJobReturn::Continuation(_)=>panic!("finite pending work must keep its genuine producer")};Ok(())})).unwrap();if delivered{break}}assert!(delivered);assert_eq!(pending_count,steps);assert_eq!(job.remaining,0);close_origin(&mut origin,&mut caller,stock);drop(origin);caller.retire(stock);
}
